"""Create a launch notice. The application requires its local data server."""
from pathlib import Path
html='<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stockscreen starten</title><style>body{background:#0c1017;color:#e6edf5;font:16px/1.7 system-ui;max-width:680px;margin:10vh auto;padding:24px}h1{font-size:30px}a{color:#d7f58a}code{background:#18212c;padding:8px;border-radius:6px}</style><h1>Stockscreen mit echten Live-Daten</h1><p>Die Anwendung läuft über einen lokalen Datenserver. Öffne <strong>Start.command</strong> im Projektordner per Doppelklick. Der Server startet und öffnet die Oberfläche automatisch.</p><p>Alternativ im Projektordner:</p><p><code>python3 server.py --open</code></p><p>Wenn der Server bereits läuft: <a href="http://127.0.0.1:8765">Stockscreen öffnen →</a></p><p>Diese Datei ist keine eigenständige Anwendung. Es gibt keinen Demo-Modus und keine eingebetteten Ersatzkurse.</p></html>'
for name in ('Stockscreen.html','Vorschau.html'):
    Path(__file__).with_name(name).write_text(html)
